import{d as t,c as n,a,t as l,h as o,w as c,k as d,l as p,m,p as u,o as g}from"./index-Bvv9JioC.js";const b={class:"min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8"},x={class:"max-w-4xl mx-auto bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden"},f={class:"px-6 py-8 md:p-12"},v={class:"bg-blue-50 border-l-4 border-blue-500 p-4 mb-8"},y={class:"text-sm text-blue-700 font-medium"},h={class:"mt-12 pt-8 border-t text-center"},q="10 junio 2026",S=t({__name:"PrivacyPolicyView",setup(P){const r=s=>{const e=document.getElementById(s);e&&e.scrollIntoView({behavior:"smooth",block:"start"})};return(s,e)=>{const i=u("router-link");return g(),n("div",b,[a("div",x,[a("div",f,[e[3]||(e[3]=a("h1",{class:"text-3xl md:text-4xl font-bold text-gray-900 mb-2"}," Privacidad y condiciones ",-1)),a("p",{class:"text-sm text-gray-500 mb-6 border-b pb-6"}," Última actualización: "+l(q)),e[4]||(e[4]=a("p",{class:"mb-6 text-gray-600 text-lg leading-relaxed"},[o(" Esta política de privacidad rige de manera general para nuestras aplicaciones móviles. Específicamente, en la plataforma de Android (Google Play), el desarrollador se identifica legalmente bajo el nombre de "),a("strong",null,"victorApp"),o(", mientras que en iOS (App Store) puede figurar bajo nombres como TecnoWorld. Al utilizar nuestras aplicaciones, usted acepta la recopilación y uso de información en relación con esta política. ")],-1)),a("div",v,[a("p",y,[e[1]||(e[1]=o(" ¿Aplicaciones específicas y delicadas? ",-1)),a("a",{onClick:e[0]||(e[0]=c(k=>r("aplicaciones-especificas"),["prevent"])),href:"#aplicaciones-especificas",class:"underline font-bold cursor-pointer hover:text-blue-900"},"Ver sección de aplicaciones específicas (ej. WorkTrack)")])]),e[5]||(e[5]=d('<h2 class="text-2xl font-semibold text-gray-800 mt-10 mb-5"> ¿Que tipo de información recolectamos? </h2><p class="mb-6 text-gray-700 leading-relaxed"> Para el correcto funcionamiento de las aplicaciones que construimos o desarrollamos, estos son algunos de los datos que recolectamos: </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Ubicación</h3><p class="mb-6 text-gray-700 leading-relaxed"> Para el caso de las aplicaciones que sea necesario, accedemos a los datos proporcionados por el GPS de su dispositivo para garantizar el correcto funcionamiento. Estos datos no son almacenados públicamente por nosotros, sino que son manejados directamente a través de proveedores confiables como <a href="https://maps.google.com" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">Google Maps</a>. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3"> Datos de Registro </h3><p class="mb-6 text-gray-700 leading-relaxed"> Quiero informarle que cada vez que utiliza mi Servicio, en caso de un error en la aplicación, recopilo datos e información (a través de productos de terceros) en su teléfono llamados Datos de registro. Estos datos de registro pueden incluir información como la dirección del Protocolo de Internet («IP») de su dispositivo, el nombre del dispositivo, la versión del sistema operativo, la configuración de la aplicación cuando utiliza mi Servicio, la hora y la fecha de uso del Servicio y otras estadísticas. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3"> Cookies y Sesiones </h3><p class="mb-6 text-gray-700 leading-relaxed"> Las cookies y sesiones son archivos con una pequeña cantidad de datos que se usa comúnmente como identificadores únicos anónimos. Esto se envian a su navegador desde los sitios web que visita y se almacenan en la memoria interna de su dispositivo. Este servicio no utiliza estas cookies explícitamente. sin embargo las aplicaciones utilizan almacenamiento en cache para guadar las sessiones, como tambien las aplicaciones pueden usar código de terceros y bibliotecas que usan cookies, cache de almacenamiento para recopilar informacion y mejorar sus servicios. Tiene la opción de aceptar o rechazar nuestras sesiones, es posible que no pueda usar algunas partes de este Servicio. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-4"> Proveedores de servicio </h3><p class="mb-3 text-gray-700 leading-relaxed"> Podemos emplear a empresas o individuos de terceros debido a las siguientes razones: </p><ul class="list-disc pl-6 mb-6 text-gray-700 space-y-2 marker:text-gray-400"><li>Para facilitar nuestros servicios;</li><li>Para proporcionar el Servicio en nuestro nombre;</li><li>Para realizar servicios relacionados con el Servicio; o</li><li>Para ayudar a analizar cómo se utiliza nuestro Servicio</li></ul><p class="mb-6 text-gray-700 leading-relaxed"> Deseo informar a los usuarios de este Servicio que estos terceros tienen acceso a su Información personal. La razón es realizar las tareas que se les asignaron en nuestro nombre. Sin embargo, están obligados a no divulgar ni utilizar la información para ningún otro propósito. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3">Seguridad</h3><p class="mb-6 text-gray-700 leading-relaxed"> Valoro su confianza en proporcionarnos su información personal, por lo tanto nos esforzamos por utilizar medios comercialmente aceptables para protegerla. Pero recuerde que ningún método de transmisión por internet o método de almacenamiento eletrónico es 100% seguro y confiable, y no puedo garantizar su seguridad absoluta. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3"> Enlaces a otros sitios </h3><p class="mb-6 text-gray-700 leading-relaxed"> Este servicios puede contener enlaces a otros sitios. Si hace click en un enlace de un tercero, será dirigido a ese sitio. Tenga en cuenta que estos sitios externos no son operados por nuestros servisios. Por lo tanto, le recomiendo que revise la Política de privacidad de estos sitios web. No tenemos control ni asumimos ninguna responsabilidad por el contenido, la política de privacidad o las prácticas de sitios o servicios de tercero. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3"> Privacidad de los menores de edad </h3><p class="mb-6 text-gray-700 leading-relaxed"> Estos Servicios no se dirigen a ninguna persona menor de 13 años. No recopilo a sabiendas información de identificación personal de niños menores de 13 años. En el caso de que descubra que un niño menor de 13 años me ha proporcionado información personal, la borro inmediatamente de nuestros servidores. Si usted es padre o tutor y sabe que su hijo nos ha proporcionado información personal, comuníquese conmigo para que pueda realizar las acciones necesarias. </p><h2 class="text-2xl font-semibold text-gray-800 mt-10 mb-5"> ¿Que hacemos con los datos que recolectamos? </h2><p class="mb-3 text-gray-700 leading-relaxed"> Los datos recolectados son de dos tipos: </p><ol class="list-decimal pl-6 mb-6 text-gray-700 space-y-2 marker:text-gray-500 font-medium"><li>Datos recolectado por nosotros.</li><li>Datos recolectado por terceros.</li></ol><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3"> Datos recolectados por nosotros </h3><p class="mb-6 text-gray-700 leading-relaxed"> Estos datos se recolectan para obtener un feedback de que es lo que quieren nuestros usuarios y así poder mejorar brindando las correctas mejoras en cada actualización. Los datos son manipulados a nivel de código, luego procesados en grandes cantidades, pero en ningún momento accedemos a datos de un usuario en particular, pues están encriptados y solo el usuario dueño de la información puede acceder a ellos. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-4"> Datos recolectados por terceros </h3><p class="mb-3 text-gray-700 leading-relaxed"> En los datos recolectados por terceros están: </p><ul class="list-disc pl-6 mb-6 text-gray-700 space-y-2 marker:text-gray-400"><li><a href="https://play.google.com/store" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">Google Play</a></li><li><a href="https://www.apple.com/app-store/" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">App Store (Apple)</a></li><li><a href="https://firebase.google.com" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">Firebase</a></li></ul><h2 id="aplicaciones-especificas" class="text-2xl font-semibold text-gray-800 mt-12 mb-5 pt-8 border-t"> Políticas para Aplicaciones Específicas </h2><p class="mb-6 text-gray-700 leading-relaxed"> Algunas de nuestras aplicaciones cuentan con funcionalidades más complejas y requieren permisos especiales. A continuación, se detalla la política legal aplicable estrictamente a estas aplicaciones en particular: </p><div class="bg-gray-100 p-6 rounded-lg mb-8 border border-gray-200"><h3 class="text-xl font-bold text-gray-900 mb-4">Aplicación: WorkTrack</h3><p class="mb-4 text-gray-700 leading-relaxed"><strong>Nombre del Desarrollador (Google Play / Android):</strong> victorApp </p><p class="mb-4 text-gray-700 leading-relaxed"><strong>Público Objetivo (Uso Empresarial):</strong> WorkTrack está diseñada específicamente como una herramienta corporativa orientada a empresas que cuentan con promotores de calle, guardias de seguridad en vecindarios o barrios, o cualquier organización que implemente políticas de monitoreo de su personal durante la jornada laboral. El objetivo de la aplicación es brindar a las empresas un mejor control logístico, seguridad y gestión operativa de sus colaboradores en campo. </p><p class="mb-2 text-gray-700 leading-relaxed"><strong>Uso y Recopilación de Ubicación (Incluyendo Segundo Plano):</strong></p><p class="mb-4 text-gray-700 leading-relaxed"> Para el correcto funcionamiento de <strong>WorkTrack</strong>, la aplicación recopila y accede a los datos de ubicación proporcionados por el GPS de su dispositivo. <strong>Esta recopilación de ubicación se realiza incluso en segundo plano (cuando la aplicación está cerrada o no está en uso)</strong>. Utilizamos estos datos exclusivamente para permitir el seguimiento continuo de sus rutas de trabajo y registrar adecuadamente su actividad según las funcionalidades principales de la aplicación. </p><p class="mb-4 text-gray-700 leading-relaxed"><strong>Control del Usuario sobre el Monitoreo:</strong> El usuario final tiene el control total para especificar cuándo puede ser monitoreado y cuándo no. El usuario puede decidir activar o inactivar la geolocalización en cualquier momento desde la configuración de su dispositivo o mediante las opciones proporcionadas dentro de la aplicación, deteniendo así cualquier recolección de datos de ubicación al instante. </p></div><h3 class="text-xl font-medium text-gray-800 mt-12 mb-3 pt-8 border-t"> Derechos de los Usuarios </h3><p class="mb-6 text-gray-700 leading-relaxed"> Normalmente en la aplicación está establecido el proceso para poder borrar sus datos o perfil. Así también, los usuarios tienen el derecho de solicitar la eliminación de su cuenta y de cualquier dato personal asociado en cualquier momento, enviando un correo electrónico directamente a nuestra información de contacto proporcionada a continuación. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3"> Cambios a esta Política </h3><p class="mb-6 text-gray-700 leading-relaxed"> Es posible que actualicemos nuestra Política de Privacidad de vez en cuando. Por lo tanto, se le recomienda revisar esta página periódicamente para ver si hay cambios. Le notificaremos de cualquier cambio publicando la nueva Política de Privacidad en esta página. Estos cambios entran en vigencia inmediatamente después de su publicación. </p><h3 class="text-xl font-medium text-gray-800 mt-8 mb-3"> Información de Contacto </h3><p class="mb-6 text-gray-700 leading-relaxed"> Si tiene alguna pregunta o sugerencia sobre nuestra Política de Privacidad, no dude en contactarnos a través del correo electrónico: <a href="mailto:victobasco@gmail.com" class="text-blue-600 hover:text-blue-800 transition-colors underline decoration-blue-300 underline-offset-2">victobasco@gmail.com</a>. </p>',35)),a("div",h,[p(i,{to:"/",class:"inline-flex items-center text-blue-600 hover:text-blue-800 font-medium"},{default:m(()=>[...e[2]||(e[2]=[a("svg",{xmlns:"http://www.w3.org/2000/svg",class:"h-5 w-5 mr-1",viewBox:"0 0 20 20",fill:"currentColor"},[a("path",{"fill-rule":"evenodd",d:"M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z","clip-rule":"evenodd"})],-1),o(" Volver al inicio ",-1)])]),_:1})])])])])}}});export{S as default};
